-- 기관 보도자료 Open API 수집처(운영자 지시 2026-10-04: 지자체 보도자료 API가 있으면 복지뉴스 아카이빙 파이프라인에 추가).
-- endpoint_url은 {key} 자리만 둔 주소 틀이다. 인증키는 수집할 때 관리자 저장값으로만 채우며 DB에는 남기지 않는다.
-- 응답에 본문(CN·contents·pstCn)이 있어도 프로필의 제목·원문 주소·게시일 세 필드만 읽는다(lib/press/open-api.ts).
-- 공공데이터포털에서 활용신청·승인(2026-10-04)했으나 원문 주소가 없어 수집처로 쓰지 않은 API: 대구 동구 보도자료 목록(15110424, REG_NO·제목·배포일만), 경북 영주시 시정뉴스(15110933, 23건·링크 없음).
-- 승인됐으나 게이트웨이가 NO_OPENAPI_SERVICE_ERROR(12)를 돌려주는 API: 경상남도_보도자료(15062546). 제공기관 배포 뒤 등록한다.
INSERT INTO press_source (source_id, organization_id, method, adapter, homepage_url, endpoint_url, allowed_hosts, interval_minutes, verification_status, verification_note, endpoint_verified_at, policy_basis, adapter_profile, registry_version) VALUES ('src:seoul:press-api', 'org:서울특별시', 'OPEN_API', 'OpenAPIAdapter', 'https://www.seoul.go.kr', 'http://openapi.seoul.go.kr:8088/{key}/json/tvReportedInfo/1/50/', '["www.seoul.go.kr"]', 60, 'ENDPOINT_VERIFIED', '서울 열린데이터광장 「서울시 보도자료」(OA-22195, 서비스 tvReportedInfo, 매일 1회 갱신). 공개 시험키(sample, 5건)로 2026-10-04 응답 확인: TITLE·PUBDATE·LINK(#view/번호)·CN(본문, 읽지 않음)·CRDNS·DEPT. 원문 주소는 기존 HTML 수집처와 같은 news_report.do?bbsNo=158&nttNo=번호로 만든다. 서울 열린데이터광장 인증키가 필요하다.', 1791120000, '서울 열린데이터광장 이용조건 공공누리 제4유형(출처표시·상업적 이용금지·변경금지). 메타데이터와 원문 링크만 보관한다.', '{"keyRef":"seoul_open_data","format":"json","rows":"tvReportedInfo.row","resultCode":"tvReportedInfo.RESULT.CODE","okCodes":["INFO-000"],"emptyCodes":["INFO-200"],"keyErrorCodes":["INFO-100"],"fields":{"title":"TITLE","link":"LINK","date":"PUBDATE"},"linkId":"#view/(?<id>[0-9]+)","url":"https://www.seoul.go.kr/news/news_report.do?bbsNo=158&nttNo={id}","sampleKey":"sample","sampleUrl":"http://openapi.seoul.go.kr:8088/{key}/json/tvReportedInfo/1/5/"}', 'press-open-api-2026-10-04') ON CONFLICT(source_id) DO UPDATE SET method = excluded.method, adapter = excluded.adapter, homepage_url = excluded.homepage_url, endpoint_url = excluded.endpoint_url, allowed_hosts = excluded.allowed_hosts, verification_status = excluded.verification_status, verification_note = excluded.verification_note, endpoint_verified_at = excluded.endpoint_verified_at, adapter_profile = excluded.adapter_profile, registry_version = excluded.registry_version;
INSERT INTO press_source (source_id, organization_id, method, adapter, homepage_url, endpoint_url, allowed_hosts, interval_minutes, verification_status, verification_note, endpoint_verified_at, policy_basis, adapter_profile, registry_version) VALUES ('src:gwacheon:press-api', 'org:경기도:과천시', 'OPEN_API', 'OpenAPIAdapter', 'https://www.gccity.go.kr', 'https://apis.data.go.kr/3970000/newsList/list?serviceKey={key}&limit=30', '["www.gccity.go.kr"]', 60, 'ENDPOINT_VERIFIED', '공공데이터포털 「경기도 과천시_보도자료」(15159541, REST, 2026-10-04 활용신청 자동승인). 계정 인증키로 응답 확인: total 2402, items[title·depart·url·createDate·contents(본문, 읽지 않음)], 최신순. numOfRows는 무시되고 limit만 건수를 줄인다.', 1791120000, '공공데이터포털 이용허락범위 제한 없음. 메타데이터와 원문 링크만 보관한다.', '{"keyRef":"data_go_kr","format":"json","rows":"items","resultCode":"success","okCodes":["true"],"fields":{"title":"title","link":"url","date":"createDate"}}', 'press-open-api-2026-10-04') ON CONFLICT(source_id) DO UPDATE SET method = excluded.method, adapter = excluded.adapter, homepage_url = excluded.homepage_url, endpoint_url = excluded.endpoint_url, allowed_hosts = excluded.allowed_hosts, verification_status = excluded.verification_status, verification_note = excluded.verification_note, endpoint_verified_at = excluded.endpoint_verified_at, adapter_profile = excluded.adapter_profile, registry_version = excluded.registry_version;
INSERT INTO press_source (source_id, organization_id, method, adapter, homepage_url, endpoint_url, allowed_hosts, interval_minutes, verification_status, verification_note, endpoint_verified_at, policy_basis, adapter_profile, registry_version) VALUES ('src:paju:press-api', 'org:경기도:파주시', 'OPEN_API', 'OpenAPIAdapter', 'https://www.paju.go.kr', 'https://apis.data.go.kr/4060000/pressrelease/pressRelease?serviceKey={key}&pageNo=1&numOfRows=30&type=json', '["www.paju.go.kr"]', 60, 'ENDPOINT_VERIFIED', '공공데이터포털 「경기도 파주시_보도자료」(15159546, REST, 2026-10-04 활용신청 자동승인). 계정 인증키로 응답 확인: totalCount 14441, item[pstTtl·pstgYmd·tkcgDeptNm·orgnlLink·pstCn(본문, 읽지 않음)], 최신순. 제목이 ''파주시 10월 2일 보도자료입니다.''처럼 하루치 묶음이라 분류는 대부분 비복지로 남는다.', 1791120000, '공공데이터포털 이용허락범위 제한 없음. 메타데이터와 원문 링크만 보관한다.', '{"keyRef":"data_go_kr","format":"json","rows":"response.body.items.item","fields":{"title":"pstTtl","link":"orgnlLink","date":"pstgYmd"}}', 'press-open-api-2026-10-04') ON CONFLICT(source_id) DO UPDATE SET method = excluded.method, adapter = excluded.adapter, homepage_url = excluded.homepage_url, endpoint_url = excluded.endpoint_url, allowed_hosts = excluded.allowed_hosts, verification_status = excluded.verification_status, verification_note = excluded.verification_note, endpoint_verified_at = excluded.endpoint_verified_at, adapter_profile = excluded.adapter_profile, registry_version = excluded.registry_version;
